upserted as (
  insert into public.products (slug, name, category_id, price, description, short_description)
  select d.slug, d.name, c.id, d.price, d.description, d.description
  from data d
  join public.categories c on c.slug = d.category_slug
  on conflict (slug) do update set
    name              = excluded.name,
    category_id       = excluded.category_id,
    price             = excluded.price,
    -- an old "previous_price" would be wrong after a price change
    previous_price    = case when excluded.price < products.previous_price then products.previous_price end,
    description       = excluded.description,
    short_description = excluded.short_description
  returning id, slug
)
-- Stock lives in the default variant (SKU = slug in uppercase)
insert into public.product_variants (product_id, sku, stock)
select u.id, upper(u.slug), d.stock
from upserted u
join data d on d.slug = u.slug
on conflict (sku) do update set stock = excluded.stock;
